<?php
define('APP_INIT', true); $pageTitle='Commission Scheme Builder'; $activeMenu='commission_engine';
require_once __DIR__ . '/../../includes/header.php'; requirePermission('commission.manage');
$db=Database::getConnection(); $tenant=TenantContext::id();
$companies=$db->prepare('SELECT id,name FROM companies WHERE tenant_id=:tenant AND status="active" ORDER BY name'); $companies->execute([':tenant'=>$tenant]); $companies=$companies->fetchAll();
?>
<div class="page-header-container"><div><h2 class="page-title">Commission Scheme Builder</h2><div class="page-subtitle">Configure company/product incentives with safe rules and preview before activation.</div></div></div>
<div class="dark-card"><form id="schemeForm"><?php echo csrfField(); ?><div class="row g-3"><div class="col-md-6"><label class="form-label-custom">Scheme name</label><input required name="name" class="form-control form-control-custom"></div><div class="col-md-3"><label class="form-label-custom">Company scope</label><select name="company_id" class="form-select form-control-custom"><option value="">Entire dealership</option><?php foreach($companies as $c): ?><option value="<?= $c['id'] ?>"><?= htmlspecialchars($c['name']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><label class="form-label-custom">Type</label><input name="scheme_type" value="Base / General Commission" class="form-control form-control-custom"></div><div class="col-md-3"><label class="form-label-custom">Basis</label><select name="basis" class="form-select form-control-custom"><option value="quantity">Quantity</option><option value="sales_amount">Sales amount</option><option value="gross_profit">Gross profit</option><option value="collection_amount">Collection amount</option><option value="target_achievement">Target achievement %</option></select></div><div class="col-md-3"><label class="form-label-custom">Method</label><select name="calculation_method" class="form-select form-control-custom"><option value="fixed_rate">Fixed rate</option><option value="percentage">Percentage</option><option value="volume_slab">Volume slab</option><option value="amount_slab">Amount slab</option><option value="target_achievement">Target slab</option></select></div><div class="col-md-3"><label class="form-label-custom">Slab mode</label><select name="slab_mode" class="form-select form-control-custom"><option value="whole">Whole / Retroactive</option><option value="progressive">Progressive / Incremental</option></select></div><div class="col-md-3"><label class="form-label-custom">Stacking</label><select name="stacking_mode" class="form-select form-control-custom"><option value="stack">Stack</option><option value="highest_only">Highest only</option><option value="exclusive">Exclusive</option><option value="conditional_stack">Conditional stack</option></select></div><div class="col-md-3"><label class="form-label-custom">Effective from</label><input type="date" name="effective_from" value="<?= date('Y-m-d') ?>" class="form-control form-control-custom"></div><div class="col-md-3"><label class="form-label-custom">Status</label><select name="status" class="form-select form-control-custom"><option value="draft">Draft</option><option value="active">Active</option></select></div></div><hr><p class="text-secondary">Slabs (JSON): for example <code>[{"from_value":0,"to_value":999,"rate":5},{"from_value":1000,"to_value":"","rate":8}]</code></p><textarea id="slabs" class="form-control form-control-custom" rows="4">[{"from_value":0,"to_value":"","rate":0,"rate_type":"fixed"}]</textarea><div class="mt-3 d-flex gap-2"><button class="btn btn-primary-custom">Save scheme</button><button type="button" id="preview" class="btn btn-outline-light">Preview at 5,500</button></div></form><pre id="result" class="mt-3 text-info"></pre></div>
<script>const f=document.getElementById('schemeForm'),slabs=document.getElementById('slabs'),result=document.getElementById('result');function data(){let d=new FormData(f);d.append('slabs',slabs.value);return d}f.onsubmit=async e=>{e.preventDefault();let r=await fetch(`${BASE_URL}/ajax/commission/save.php`,{method:'POST',body:data()});result.textContent=JSON.stringify(await r.json(),null,2)};document.getElementById('preview').onclick=async()=>{let d=data();d.append('scheme',JSON.stringify({basis:f.basis.value,calculation_method:f.calculation_method.value,slab_mode:f.slab_mode.value,rate:0}));d.append('facts',JSON.stringify({quantity:5500,sales_amount:0,target_achievement:110}));let r=await fetch(`${BASE_URL}/ajax/commission/preview.php`,{method:'POST',body:d});result.textContent=JSON.stringify(await r.json(),null,2)};</script>
